/// The token scale a glyph renders at.
enum GlyphSize {
    case sm, md, lg

    var points: CGFloat {
        switch self {
        case .sm: return 16
        case .md: return 24
        case .lg: return 32
        }
    }
}

/// One glyph from the library, template-rendered in a token colour.
struct Glyph: View {
    let name: GlyphName
    var size: GlyphSize = .md
    var tint: Color = Token.textPrimary

    init(_ name: GlyphName, size: GlyphSize = .md, tint: Color = Token.textPrimary) {
        self.name = name
        self.size = size
        self.tint = tint
    }

    var body: some View {
        Image(name.rawValue, bundle: .ui2Preview)
            .renderingMode(.template)
            .resizable()
            .scaledToFit()
            .frame(width: size.points, height: size.points)
            .foregroundStyle(tint)
            .accessibilityLabel(name.label)
    }
}
